create extension if not exists vector with schema extensions;
create table if not exists public.notebooks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, title text not null check(length(title)<=100), description text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.sources (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, notebook_id uuid not null references public.notebooks on delete cascade, title text not null, kind text not null, status text not null default 'processing' check(status in ('processing','ready','failed')), storage_path text not null, error_message text, page_count integer, created_at timestamptz not null default now());
create table if not exists public.document_chunks (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,notebook_id uuid not null references public.notebooks on delete cascade,source_id uuid not null references public.sources on delete cascade,chunk_index integer not null,content text not null,location text,embedding vector(3072),created_at timestamptz not null default now(),unique(source_id,chunk_index));
create index if not exists document_chunks_embedding_idx on public.document_chunks using hnsw (embedding vector_cosine_ops);
create index if not exists document_chunks_notebook_idx on public.document_chunks(notebook_id);
create table if not exists public.messages (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,notebook_id uuid not null references public.notebooks on delete cascade,role text not null check(role in ('user','assistant')),content text not null,citations jsonb not null default '[]',created_at timestamptz not null default now());
create table if not exists public.notes (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,notebook_id uuid not null references public.notebooks on delete cascade,title text not null default 'Untitled note',content text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.study_materials (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,notebook_id uuid not null references public.notebooks on delete cascade,kind text not null,payload jsonb not null,created_at timestamptz not null default now());
create table if not exists public.shares (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,notebook_id uuid not null references public.notebooks on delete cascade,token text not null unique,created_at timestamptz not null default now(),expires_at timestamptz);
do $$ declare t text; begin foreach t in array array['notebooks','sources','document_chunks','messages','notes','study_materials','shares'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy owner_select on public.%I for select using (auth.uid() = user_id)',t); execute format('create policy owner_insert on public.%I for insert with check (auth.uid() = user_id)',t); execute format('create policy owner_update on public.%I for update using (auth.uid() = user_id) with check (auth.uid() = user_id)',t); execute format('create policy owner_delete on public.%I for delete using (auth.uid() = user_id)',t); end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('sources','sources',false,20971520,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain','text/markdown']) on conflict(id) do nothing;
create policy "owner source storage" on storage.objects for all using (bucket_id='sources' and (storage.foldername(name))[1]=auth.uid()::text) with check (bucket_id='sources' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.match_document_chunks(query_embedding vector(3072), match_notebook uuid, match_count int default 8) returns table(id uuid,source_id uuid,content text,location text,similarity float) language sql stable security invoker set search_path=public as $$ select c.id,c.source_id,c.content,c.location,1-(c.embedding<=>query_embedding) similarity from document_chunks c where c.notebook_id=match_notebook and c.user_id=auth.uid() and c.embedding is not null order by c.embedding<=>query_embedding limit match_count $$;
